LIBRARY ieee;

USE ieee.std_logic_1164.all;
PACKAGE ccs_ctrl_in_buf_wait_pkg_v4 IS

COMPONENT ccs_ctrl_in_buf_wait_v4
  GENERIC (
    rscid    : INTEGER := 1;
    width    : INTEGER := 8;
    ph_clk   : INTEGER RANGE 0 TO 1 := 1;
    ph_en    : INTEGER RANGE 0 TO 1 := 1;
    ph_arst  : INTEGER RANGE 0 TO 1 := 1;
    ph_srst  : INTEGER RANGE 0 TO 1 := 1
  );
  PORT (
    clk     : IN  std_logic;
    en      : IN  std_logic;
    arst    : IN  std_logic;
    srst    : IN  std_logic;
    idat    : OUT std_logic_vector(width-1 DOWNTO 0);
    rdy     : OUT std_logic;
    ivld    : OUT std_logic;
    dat     : IN  std_logic_vector(width-1 DOWNTO 0);
    irdy    : IN  std_logic;
    vld     : IN  std_logic;
    is_idle : out std_logic
   );
END COMPONENT;

END ccs_ctrl_in_buf_wait_pkg_v4;

LIBRARY ieee;

USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all; -- Prevent STARC 2.1.1.2 violation

ENTITY ccs_ctrl_in_buf_wait_v4 IS
  GENERIC (
    rscid    : INTEGER := 1;
    width    : INTEGER := 8;
    ph_clk   : INTEGER RANGE 0 TO 1 := 1;
    ph_en    : INTEGER RANGE 0 TO 1 := 1;
    ph_arst  : INTEGER RANGE 0 TO 1 := 1;
    ph_srst  : INTEGER RANGE 0 TO 1 := 1
  );
  PORT (
    clk     : IN  std_logic;
    en      : IN  std_logic;
    arst    : IN  std_logic;
    srst    : IN  std_logic;
    idat    : OUT std_logic_vector(width-1 DOWNTO 0);
    rdy     : OUT std_logic;
    ivld    : OUT std_logic;
    dat     : IN  std_logic_vector(width-1 DOWNTO 0);
    irdy    : IN  std_logic;
    vld     : IN  std_logic;
    is_idle : OUT std_logic
  );
END ccs_ctrl_in_buf_wait_v4;

ARCHITECTURE beh OF ccs_ctrl_in_buf_wait_v4 IS
  SIGNAL rdy_int    : std_logic;
  SIGNAL vld_int    : std_logic;
  SIGNAL filled     : std_logic;
  SIGNAL filled_next: std_logic;
  SIGNAL lbuf       : std_logic;
  SIGNAL abuf       : std_logic_vector(width-1 DOWNTO 0);
  SIGNAL hs_init    : std_logic;

BEGIN
  rdy_int <= NOT filled OR irdy;
  rdy <= rdy_int AND hs_init;
  vld_int <= vld AND hs_init;

  ivld <= filled_next;
  idat <= abuf;

  lbuf <= vld_int AND rdy_int;
  filled_next <= vld_int OR (filled AND NOT irdy);

  is_idle <= NOT lbuf AND (filled XNOR filled_next) AND hs_init;

  POSEDGE_CLK: IF ph_clk=1 GENERATE
    STATEPOS: PROCESS ( clk, arst )
    BEGIN
      IF conv_integer(arst) = ph_arst THEN
        filled <= '0';
        hs_init <= '0';
      ELSIF clk'EVENT AND clk = '1' THEN
        IF conv_integer(srst) = ph_srst THEN
          filled <= '0';
          hs_init <= '0';
        ELSIF conv_integer(en) = ph_en THEN
          filled <= filled_next;
          hs_init <= '1';
        END IF;
      END IF;
    END PROCESS;

    BUFPOS: PROCESS ( clk, arst )
    BEGIN
      IF conv_integer(arst) = ph_arst THEN
        abuf <= (others => '0');
      ELSIF clk'EVENT AND clk = '1' THEN
        IF conv_integer(srst) = ph_srst THEN
          abuf <= (others => '0');
        ELSIF (conv_integer(en) = ph_en) AND (lbuf = '1') THEN
          abuf <= dat;
        END IF;
      END IF;
    END PROCESS;
  END GENERATE;

  NEGEDGE_CLK: IF ph_clk=0 GENERATE
    STATENEG: PROCESS ( clk, arst )
    BEGIN
      IF conv_integer(arst) = ph_arst THEN
        filled <= '0';
        hs_init <= '0';
      ELSIF clk'EVENT AND clk = '0' THEN
        IF conv_integer(srst) = ph_srst THEN
          filled <= '0';
          hs_init <= '0';
        ELSIF conv_integer(en) = ph_en THEN
          filled <= filled_next;
          hs_init <= '1';
        END IF;
      END IF;
    END PROCESS;

    BUFNEG: PROCESS ( clk, arst )
    BEGIN
      IF conv_integer(arst) = ph_arst THEN
        abuf <= (others => '0');
      ELSIF clk'EVENT AND clk = '0' THEN
        IF conv_integer(srst) = ph_srst THEN
          abuf <= (others => '0');
        ELSIF (conv_integer(en) = ph_en) AND (lbuf = '1') THEN
          abuf <= dat;
        END IF;
      END IF;
    END PROCESS;
  END GENERATE;
END beh;


