LIBRARY ieee;

USE ieee.std_logic_1164.all;
USE ieee.std_logic_unsigned.all;

PACKAGE ccs_out_buf_wait_pkg_v5 IS

COMPONENT ccs_out_buf_wait_v5
  GENERIC (
    rscid   : INTEGER := 1;
    width   : INTEGER := 8;
    ph_clk  : INTEGER RANGE 0 TO 1 := 1;
    ph_en   : INTEGER RANGE 0 TO 1 := 1;
    ph_arst : INTEGER RANGE 0 TO 1 := 1;
    ph_srst : INTEGER RANGE 0 TO 1 := 1;
    rst_val : INTEGER := 0
  );
  PORT (
    clk     : IN  std_logic;
    en      : IN  std_logic;
    arst    : IN  std_logic;
    srst    : IN  std_logic;
    dat     : OUT std_logic_vector(width-1 DOWNTO 0);
    irdy    : OUT std_logic;
    vld     : OUT std_logic;
    idat    : IN  std_logic_vector(width-1 DOWNTO 0);
    rdy     : IN  std_logic;
    ivld    : IN  std_logic;
    is_idle : OUT std_logic
   );
END COMPONENT;

END ccs_out_buf_wait_pkg_v5;

LIBRARY ieee;

USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all; -- Prevent STARC 2.1.1.2 violation


ENTITY ccs_out_buf_wait_v5 IS
  GENERIC (
    rscid   : INTEGER := 1;
    width   : INTEGER := 8;
    ph_clk  : INTEGER RANGE 0 TO 1 := 1;
    ph_en   : INTEGER RANGE 0 TO 1 := 1;
    ph_arst : INTEGER RANGE 0 TO 1 := 1;
    ph_srst : INTEGER RANGE 0 TO 1 := 1;
    rst_val : INTEGER := 0
  );
  PORT (
    clk     : IN  std_logic;
    en      : IN  std_logic;
    arst    : IN  std_logic;
    srst    : IN  std_logic;
    dat     : OUT std_logic_vector(width-1 DOWNTO 0);
    irdy    : OUT std_logic;
    vld     : OUT std_logic;
    idat    : IN  std_logic_vector(width-1 DOWNTO 0);
    rdy     : IN  std_logic;
    ivld    : IN  std_logic;
    is_idle : OUT std_logic
  );
END ccs_out_buf_wait_v5;

ARCHITECTURE beh OF ccs_out_buf_wait_v5 IS
  SIGNAL filled     : std_logic;
  SIGNAL filled_next: std_logic;
  SIGNAL lbuf       : std_logic;
  SIGNAL abuf       : std_logic_vector(width-1 DOWNTO 0);

BEGIN
  irdy <= NOT filled_next;

  vld <= filled OR ivld;
  dat <= abuf WHEN filled = '1' ELSE idat;

  lbuf <= ivld AND NOT filled AND NOT rdy;
  filled_next <= NOT rdy WHEN filled = '1' ELSE lbuf;

  is_idle <= NOT lbuf AND (filled XNOR filled_next);

  POSEDGE_CLK: IF ph_clk=1 GENERATE
    STATEPOS: PROCESS ( clk, arst )
    BEGIN
      IF conv_integer(arst) = ph_arst THEN
        filled <= '0';
      ELSIF clk'EVENT AND clk = '1' THEN
        IF conv_integer(srst) = ph_srst THEN
          filled <= '0';
        ELSIF conv_integer(en) = ph_en THEN
          filled <= filled_next;
        END IF;
      END IF;
    END PROCESS;

    BUFPOS: PROCESS ( clk, arst )
    BEGIN
      IF conv_integer(arst) = ph_arst THEN
        abuf <= conv_std_logic_vector(rst_val, width);
      ELSIF clk'EVENT AND clk = '1' THEN
        IF conv_integer(srst) = ph_srst THEN
          abuf <= conv_std_logic_vector(rst_val, width);
        ELSIF (conv_integer(en) = ph_en) AND (lbuf = '1') THEN
          abuf <= idat;
        END IF;
      END IF;
    END PROCESS;
  END GENERATE;

  NEGEDGE_CLK: IF ph_clk=0 GENERATE
    STATENEG: PROCESS ( clk, arst )
    BEGIN
      IF conv_integer(arst) = ph_arst THEN
        filled <= '0';
      ELSIF clk'EVENT AND clk = '0' THEN
        IF conv_integer(srst) = ph_srst THEN
          filled <= '0';
        ELSIF conv_integer(en) = ph_en THEN
          filled <= filled_next;
        END IF;
      END IF;
    END PROCESS;

    BUFNEG: PROCESS ( clk, arst )
    BEGIN
      IF conv_integer(arst) = ph_arst THEN
        abuf <= conv_std_logic_vector(rst_val, width);
      ELSIF clk'EVENT AND clk = '0' THEN
        IF conv_integer(srst) = ph_srst THEN
          abuf <= conv_std_logic_vector(rst_val, width);
        ELSIF (conv_integer(en) = ph_en) AND (lbuf = '1') THEN
          abuf <= idat;
        END IF;
      END IF;
    END PROCESS;
  END GENERATE;

END beh;

