        IF ( emit_p5_skeleton_for_C_0_tr0 = '1' ) THEN
          state_var_NS <= main_C_0;
        ELSE
          state_var_NS <= emit_p5_skeleton_for_for_C_0;
        END IF;
      -- run_rlp_C_0
      WHEN OTHERS =>
        fsm_output <= STD_LOGIC_VECTOR'( "0000000000");
        state_var_NS <= b2_w_ds_vinit_C_0;
    END CASE;
  END PROCESS GPTBackbonePhase3_run_run_fsm_1;

  GPTBackbonePhase3_run_run_fsm_1_REG : PROCESS (clk)
  BEGIN
    IF clk'event AND ( clk = '1' ) THEN
      IF ( rst = '1' ) THEN
        state_var <= run_rlp_C_0;
      ELSE
        IF ( run_wen = '1' ) THEN
          state_var <= state_var_NS;
        END IF;
      END IF;
    END IF;
  END PROCESS GPTBackbonePhase3_run_run_fsm_1_REG;

END v1;

